open Num

(*
Suppose 

  f(0) = 1, 
  f(1) = 2, 
  8*f(n)*f(n+1) - 6*f(n)*f(n+2) + f(n+1)*f(n+2) = 0 

(40 pts) Calculate f(n) for any integer n >= 0. Replace "todo" with your own implementation.

Hint: You can replace n with n'-2. In that case, n+1=n'-1; n+2=n'.
*)

let rec f (n:int) : string =
  let rec pow2 n =
    if n = 0 then Num.num_of_int 1
    else Num.num_of_int 2 */ pow2 (n-1)
  in
  string_of_num (pow2 n)
;;



printf "%d - %s\n" 7 (f 7); (* This is your own way of quick manual testing. *)

open OUnit

module Tests = struct

    let testingPrint act exp =
      print_string "Expected ";
      print_string exp;
      print_endline "\n got ";
      print_string act;
      print_endline "\n-----";;

    let testing n expectedOutput =
      let act = f n in
        printf "Testing func %d:\n" n;
        testingPrint act expectedOutput; 
        print_endline ""; 
        assert_equal expectedOutput act;;

    let suite = 
        "func" >:::
            [              
              "n = 14" >:: (fun _ -> testing 14 "16384";);         
              "n = 17" >:: (fun _ -> testing 17 "131072";);
              "n = 21" >:: (fun _ -> testing 21 "2097152";);
              "n = 35" >:: (fun _ -> testing 35 "34359738368";);         
              "n = 43" >:: (fun _ -> testing 43 "8796093022208";);         
              "n = 55" >:: (fun _ -> testing 55 "36028797018963968";);         
              "n = 67" >:: (fun _ -> testing 67 "147573952589676412928";);         
              "n = 71" >:: (fun _ -> testing 71 "2361183241434822606848";);         
              "n = 81" >:: (fun _ -> testing 81 "2417851639229258349412352";);  
              "n = 200" >:: (fun _ -> testing 200 "1606938044258990275541962092341162602522202993782792835301376";);
              "n = 1000" >:: (fun _ -> testing 1000 "";);
              "n = 10000" >:: (fun _ -> testing 10000 "";);
            ]
        
    ;;
end  

let _ =
  run_test_tt_main Tests.suite
;;